import{_ as o,a0 as r,w as c,s as g,ao as n,I as a,x as e,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何将 Oracle 11g 升级到 Orcale 12c | LCTT x X-CMD","titleTemplate":false,"description":"如何将 Oracle 11g 升级到 Orcale 12c | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何将 Oracle 11g 升级到 Orcale 12c | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何将 Oracle 11g 升级到 Orcale 12c | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c","title":"如何将 Oracle 11g 升级到 Orcale 12c","tag":"201510","desc":""},"relativePath":"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c.md","filePath":"[post].md"}'),s={name:"201510/20150923 How To Upgrade From Oracle 11g To Oracle 12c.md"};function m(w,l,d,u,x,b){const t=r("Link");return c(),g("div",null,[l[20]||(l[20]=n('<h1 id="如何将-oracle-11g-升级到-orcale-12c" tabindex="-1">如何将 Oracle 11g 升级到 Orcale 12c <a class="header-anchor" href="#如何将-oracle-11g-升级到-orcale-12c" aria-label="Permalink to “如何将 Oracle 11g 升级到 Orcale 12c”">​</a></h1><p>大家好。今天我们来学习一下如何将 Oracle 11g 升级到 Oracle 12c。开始吧。</p><p>在此，我使用的是 CentOS 7 64 位 Linux 发行版。我假设你已经在你的系统上安装了 Oracle 11g。这里我会展示一下安装 Oracle 11g 时我的操作步骤。</p><p>我在 Oracle 11g 上选择 “Create and configure a database”，如下图所示。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage1.png" alt=""></p><p>然后我选择安装 Oracle 11g “Decktop Class”。如果是生产环境，你必须选择 “Server Class”。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage2.png" alt=""></p><p>然后你输入安装 Oracle 11g 的各种路径以及密码。下面是我自己的 Oracle 11g 安装配置。确保你正确输入了 Oracle 的密码。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage3.png" alt=""></p><p>下一步，我按照如下设置 Inventory Directory。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage4.png" alt=""></p><p>到这里，我已经向你展示了我安装 Oracle 11g 所做的工作，因为我们开始想升级到 12c。</p><p>让我们将 Oracle 11g 升级到 Oracle 12c 吧。</p>',13)),a("p",null,[l[1]||(l[1]=e("你需要从该",-1)),i(t,{href:"http://www.oracle.com/technetwork/database/enterprise-edition/downloads/database12c-linux-download-1959253.html"},{default:p(()=>[...l[0]||(l[0]=[e("链接",-1)])]),_:1}),l[2]||(l[2]=e("上下载两个 zip 文件。下载并解压两个文件到相同目录。文件名为 ",-1)),l[3]||(l[3]=a("strong",null,"linuxamd64_12c_database_1of2.zip",-1)),l[4]||(l[4]=e(" & ",-1)),l[5]||(l[5]=a("strong",null,"linuxamd64_12c_database_2of2.zip",-1)),l[6]||(l[6]=e("。提取或解压完后，它会创建一个名为 database 的文件夹。",-1))]),l[21]||(l[21]=n(`<p>注意：升级到 12c 之前，请确保在你的 CentOS 上已经安装了所有必须的软件包，并且所有的路径变量也已经正确配置，还有其它前提条件也已经满足。</p><p>下面是必须使用正确版本安装的一些软件包</p><ul><li>binutils</li><li>compat-libstdc++</li><li>gcc</li><li>glibc</li><li>libaio</li><li>libgcc</li><li>libstdc++</li><li>make</li><li>sysstat</li><li>unixodbc</li></ul><p>在因特网上搜索正确的 rpm 版本。</p><p>你也可以用一个查询处理多个软件包，然后在输出中查找正确版本。例如，在终端中输入下面的命令：</p><pre><code>rpm -q binutils compat-libstdc++ gcc glibc libaio libgcc libstdc++ make sysstat unixodbc
</code></pre><p>你的系统中必须安装了以下软件包（版本可能或新或旧）</p><ul><li>binutils-2.23.52.0.1-12.el7.x86_64</li><li>compat-libcap1-1.10-3.el7.x86_64</li><li>gcc-4.8.2-3.el7.x86_64</li><li>gcc-c++-4.8.2-3.el7.x86_64</li><li>glibc-2.17-36.el7.i686</li><li>glibc-2.17-36.el7.x86_64</li><li>glibc-devel-2.17-36.el7.i686</li><li>glibc-devel-2.17-36.el7.x86_64</li><li>ksh</li><li>libaio-0.3.109-9.el7.i686</li><li>libaio-0.3.109-9.el7.x86_64</li><li>libaio-devel-0.3.109-9.el7.i686</li><li>libaio-devel-0.3.109-9.el7.x86_64</li><li>libgcc-4.8.2-3.el7.i686</li><li>libgcc-4.8.2-3.el7.x86_64</li><li>libstdc++-4.8.2-3.el7.i686</li><li>libstdc++-4.8.2-3.el7.x86_64</li><li>libstdc++-devel-4.8.2-3.el7.i686</li><li>libstdc++-devel-4.8.2-3.el7.x86_64</li><li>libXi-1.7.2-1.el7.i686</li><li>libXi-1.7.2-1.el7.x86_64</li><li>libXtst-1.2.2-1.el7.i686</li><li>libXtst-1.2.2-1.el7.x86_64</li><li>make-3.82-19.el7.x86_64</li><li>sysstat-10.1.5-1.el7.x86_64</li></ul><p>你也需要 unixODBC-2.3.1 或更新版本的驱动。</p><p>我希望你安装 Oracle 11g 的时候已经在你的 CentOS 7 上创建了名为 oracle 的用户。让我们以用户 oracle 登录 CentOS。以用户 oracle 登录到 CentOS 之后，在你的 CentOS上打开一个终端。</p><p>使用终端更改工作目录并导航到你解压两个 zip 文件的目录。在终端中输入以下命令开始安装 12c。</p><pre><code>./runInstaller
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212image5.png" alt=""></p><p>如果一切顺利，你会看到类似下面的截图，已经开始安装 12c。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage6.png" alt=""></p><p>然后你可以选择跳过更新或者下载最近更新。如果是生产服务器，建议你必须更新。我这里选择跳过。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage7.png" alt=""></p><p>现在，选择升级现有数据库。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage8.png" alt=""></p><p>对于语言，这里已经有 English。点击下一步继续，或者你可以根据你的需要添加语言。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage9.png" alt=""></p><p>现在，选择企业版。你可以根据你的需求选择。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage10.png" alt=""></p><p>然后选择软件位置路径，这些都是不言自明的。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage11.png" alt=""></p><p>对于第七步，像下面这样使用默认的选择继续下一步。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage12.png" alt=""></p><p>在第九步中，你会看到一个类似下面这样的总结报告。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage13.png" alt=""></p><p>如果一切正常，你可以点击第九步中的 install 开始安装，进入第十步。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/11g212cimage14.png" alt=""></p><p>其中你可能会遇到一些错误，你需要通过谷歌找到这些错误的解决方法。你可能遇到的问题会有很多，因此我没有在这里详细介绍。</p><p>要有耐心，一步一步走下来最后它会告诉你成功了。否则，在谷歌上搜索做必要的操作解决问题。再一次说明，由于你可能会遇到的错误有很多，我无法在这里提供所有详细介绍。</p><p>现在，只需要按照下面屏幕指令配置监听器。</p><p>配置完监听器之后，它会启动数据库升级助手（Database Upgrade Assistant）。选择 Upgrade Oracle Database。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/DUAimage15.png" alt=""></p><p>在第二步，你会发现它显示了 11g 的位置路径以及 12c 的位置路径。同时你也会发现它指示说从原来的 Oracle Home Release 11 安装 Oracle Home Release 12.点击下一步进入步骤三。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/DUAimage16.png" alt=""></p><p>按照屏幕上的说明完成安装。</p><p>在最后一步，你会看到一个成功窗口，其中你会看到成功升级了 oracle 数据库。</p><p><strong>一个忠告</strong>：对于你的生产服务器，在升级到 12c 之前，请确保你已经在其它平台上测试过，以便你能修复升级过程中遇到的所有错误。永远不要尝试一无所知的时候就升级生产服务器。</p><hr>`,42)),a("p",null,[l[8]||(l[8]=e("via: ",-1)),i(t,{href:"http://www.unixmen.com/upgrade-from-oracle-11g-to-oracle-12c/"},{default:p(()=>[...l[7]||(l[7]=[e("http://www.unixmen.com/upgrade-from-oracle-11g-to-oracle-12c/",-1)])]),_:1})]),a("p",null,[l[12]||(l[12]=e("作者：",-1)),i(t,{href:"http://www.unixmen.com/author/forhad/"},{default:p(()=>[...l[9]||(l[9]=[e("Mohammad Forhad Iftekher",-1)])]),_:1}),l[13]||(l[13]=e(" 译者：",-1)),i(t,{href:"http://www.mutouxiaogui.cn/blog/"},{default:p(()=>[...l[10]||(l[10]=[e("ictlyh",-1)])]),_:1}),l[14]||(l[14]=e(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...l[11]||(l[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[l[17]||(l[17]=e("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...l[15]||(l[15]=[e("LCTT",-1)])]),_:1}),l[18]||(l[18]=e(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...l[16]||(l[16]=[e("Linux中国",-1)])]),_:1}),l[19]||(l[19]=e(" 荣誉推出",-1))])])}const _=o(s,[["render",m]]);export{f as __pageData,_ as default};
